import { isString } from 'lodash';
import { integer, number, OPTIONS, required } from './';

function validate(validators, value, object) {
  return validators.reduce((errors, validator) => {
    const params = {
      errors,
      object,
      value,
    };

    if (!isString(validator)) {
      return validator(params);
    }

    switch (validator) {
      case OPTIONS.integer:
        return integer(params);
      case OPTIONS.number:
        return number(params);
      case OPTIONS.required:
        return required(params);
      default:
        return errors;
    }
  }, []);
}

export default validate;
